// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        // Bound deposits to reasonable values
        deposit1 = bound(deposit1, 1, 1e18);
        deposit2 = bound(deposit2, 1, 1e18);
        collectAmt = bound(collectAmt, 0, deposit1 + deposit2);

        // Initialize contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Deposit some funds
        vm.deal(caller, deposit1 + deposit2 + 1e18);
        vm.prank(caller);
        c.Deposit{value: deposit1}();

        vm.prank(caller);
        c.Deposit{value: deposit2}();

        // Record balance before Collect
        uint256 balBefore = c.balances(caller);

        // Execute Collect - may revert if condition not met
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // If collect succeeded, balance should have decreased
        uint256 balAfter = c.balances(caller);
        if (ok) {
            assertTrue(balAfter <= balBefore - collectAmt, "Balance not reduced correctly");
        } else {
            // If reverted, balance must remain unchanged
            assertTrue(balAfter == balBefore, "Balance changed on revert");
        }
    }
}

