        // Restrict inputs to avoid overflow/revert
        depositAmount = bound(depositAmount, 0, 1e30);
        collectAmount = bound(collectAmount, 0, 1e30);
        minSum = bound(minSum, 0, 1e30);

        // Setup: set MinSum and initialize
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit from caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = c.balances(caller);

        // Try Collect
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

