    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 initialBalance, uint256 minSum, uint256 collectAmt) public {
        // Restrict inputs: minSum must be reasonable, collectAmt <= initialBalance
        vm.assume(initialBalance > 0);
        vm.assume(minSum <= initialBalance);
        vm.assume(collectAmt > 0 && collectAmt <= initialBalance);

        // Setup: set MinSum, initialize contract, fund sender
        vm.prank(address(0xdead));
        c.SetMinSum(minSum);
        vm.prank(address(0xdead));
        c.SetLogFile(address(0));
