        uint256 balanceBefore = c.balances(sender);

        // Call Collect
        vm.prank(sender);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // Only check if Collect succeeded
        if (success) {
            uint256 balanceAfter = c.balances(sender);
