pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint _am, uint _initialBalance, uint _minSum, address _caller) public {
        vm.assume(_caller != address(0));
        vm.assume(_initialBalance >= _am);
        _minSum = bound(_minSum, 0, type(uint256).max - 1);

        // Setup: initialize contract and set MinSum
        c.SetLogFile(address(0xdead));
        c.SetMinSum(_minSum);
        c.Initialized();

        // Give _caller some initial balance via Deposit
        vm.deal(_caller, _initialBalance);
        vm.prank(_caller);
        c.Deposit{value: _initialBalance}();

        uint preContractBalance = address(c).balance;
        uint preCallerBalance = address(_caller).balance;
        uint preCallerInContract = c.balances(_caller);

        // Call Collect
        vm.prank(_caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));

        if (!success) {
            // When revert, balances unchanged
            assertTrue(c.balances(_caller) == preCallerInContract);
        } else {
            // When success, caller balance in contract decreased by _am
            uint postCallerInContract = c.balances(_caller);
            assertTrue(preCallerInContract - _am == postCallerInContract);
        }
    }
}

