contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 balance, uint256 amount, address sender) public {
        // Restrict inputs so the reference condition is cleanly testable
        vm.assume(balance > 0 && amount > 0 && sender != address(0));
        // Set up contract state: set MinSum and fund the sender
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(sender, balance);
        vm.prank(sender);
        c.Deposit{value: balance}();

        // Now call Collect with amount; remember if it reverts
        vm.prank(sender);
        try c.Collect(amount) {
            // Did not revert
        } catch {
            // Reverted; we assert nothing about balances because the call failed
            assertTrue(true); // placeholder, will be replaced
            return;
        }

        // If we got here, Collect succeeded
        // The reference condition requires: balances[sender] >= minSum AND balances[sender] >= amount
        // Since we already checked the balance is at least minSum (or the call would revert), we just check the second part
        // Actually, we need to check that the caller's balance after success is at least minSum
        // But we can directly check: if the sender's balance BEFORE Collect was less than minSum, then Collect must revert.
        // We already know it didn't revert, so balance >= minSum must hold.
        assertTrue(c.balances(sender) + amount >= minSum);
    }
}

