pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 collectAmount, uint256 otherDepositAmount) public {
        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // Ensure depositAmount is 0 so that caller never actually deposits (bug: balances doesn't increase)
        vm.assume(depositAmount == 0);

        // Give caller some ether to deposit and for gas
        vm.deal(caller, 1 ether);

        // Call Deposit with 0 value (caller deposits nothing)
        vm.prank(caller);
        c.Deposit{value: 0}();

        // Now another address makes a deposit to change total contract balance, but caller still has 0
        vm.deal(address(0xdead), 1 ether);
        vm.prank(address(0xdead));
        c.Deposit{value: otherDepositAmount}();

        // Try to Collect from caller
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // If Collect didn't revert, then caller's balance should still be 0 (since they never deposited)
        if (success) {
            assertTrue(c.balances(caller) == 0);
        } else {
            // If it reverted, caller's balance remains 0 (no change)
            assertTrue(c.balances(caller) == 0);
        }
    }
}

