pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address addr1, uint256 dep1, address addr2, uint256 dep2, uint256 collectAmt) public {
        // Bound inputs to reasonable ranges
        dep1 = bound(dep1, 0, 1e18);
        dep2 = bound(dep2, 0, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);

        // Initialize contract (must be done once)
        vm.assume(!c.intitalized());
        c.SetMinSum(0);
        c.SetLogFile(address(0));
        c.Initialized();

        // First deposit from addr1
        vm.deal(addr1, dep1);
        vm.prank(addr1);
        c.Deposit{value: dep1}();

        // Second deposit from addr2
        vm.deal(addr2, dep2);
        vm.prank(addr2);
        c.Deposit{value: dep2}();

        // Collect from addr1
        vm.prank(addr1);
        (bool success,) = address(c).call{gas: 1000000}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // The general rule: sum of all balances equals contract ether balance
        // We check two arbitrary addresses (addr1, addr2) and assume others are zero
        uint256 sumBalances = c.balances(addr1) + c.balances(addr2);
        uint256 contractBalance = address(c).balance;

        assertTrue(sumBalances == contractBalance, "Sum of balances != contract balance");
    }
}

