    }

    function testFuzz_property(address caller, uint256 depositAlice, uint256 depositBob, uint256 collectAmt, bool affectOther) public {
        // Bound inputs to reasonable ranges
        depositAlice = bound(depositAlice, 0, 10 ether);
        depositBob = bound(depositBob, 0, 10 ether);
        collectAmt = bound(collectAmt, 0, 5 ether);

