            vm.deal(caller, 10 ether);
        } else {
            vm.assume(caller == alice || caller == bob);
        }

        // Initialize the contract and set MinSum
        c.SetMinSum(1); // Allow collecting small amounts
        c.Initialized();

        // Perform deposits
        vm.prank(alice);
        if (depositAlice > 0) {
            c.Deposit{value: depositAlice}();
        }
        vm.prank(bob);
        if (depositBob > 0) {
            c.Deposit{value: depositBob}();
        }

