        uint256 balAliceBefore = c.balances(alice);
        uint256 balBobBefore = c.balances(bob);
        uint256 balOtherBefore = c.balances(other);
        uint256 totalBefore = balAliceBefore + balBobBefore + balOtherBefore;

        // Execute collect
