import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, 1, 1e18);
        collectAmount = bound(collectAmount, 0, depositAmount);

        // Set up the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund sender and deposit
