pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(
        address caller,
        uint256 am,
        uint256 minSum,
        uint256 depositAmount
    ) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        am = bound(am, 1, 1e18);
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, minSum, 1e18);

        // Setup: initialize contract, set MinSum, fund caller
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();
        vm.deal(caller, depositAmount + am);

        // Deposit enough so caller has balance >= minSum and >= am
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, am));

        if (success) {
            // If successful, contract balance should decrease by exactly am
            assertTrue(address(c).balance == balanceBefore - am, "Contract balance should decrease by am");
        } else {
            // If reverted, balance unchanged
            assertTrue(address(c).balance == balanceBefore, "Contract balance should remain unchanged");
        }
    }
}
